package pay.refunds;

public record Refund(long id, long orderId, BigDecimal amount, RefundStatus status, String idempotencyKey) {
    public static Refund pending(Order order, BigDecimal amount, String key) {   // new
        return new Refund(0, order.id(), amount, RefundStatus.PENDING, key);
    }
}

package pay.refunds;

public class RefundService {
    private static final Duration WINDOW = Duration.ofDays(30);      // R-1
    private static final BigDecimal SMALLEST = new BigDecimal("0.01"); // R-2
    private final Orders orders;     // existing
    private final Refunds refunds;   // new in P1
    private final Clock clock;

    // constructor: same as OrderCancelService.java:7-10

    public Refund request(long orderId, BigDecimal amount, String key, User by) {
        Order order = orders.findOwned(orderId, by);          // existing: 403 for a stranger
        order.requireStatus(OrderStatus.PAID);                // existing
        if (order.paidAt().plus(WINDOW).isBefore(clock.instant())) {   // existing: paidAt()
            throw RefundErrors.windowClosed();                // new: 422 REFUND_WINDOW_CLOSED
        }
        if (amount.compareTo(SMALLEST) < 0) {
            throw RefundErrors.tooSmall();                    // new: 422 REFUND_TOO_SMALL
        }
        return refunds.findByKey(key)                         // same key, same refund
            .orElseGet(() -> refunds.save(Refund.pending(order, amount, key)));
    }
}

package pay.refunds;

public class RefundJob {
    private static final int MAX_TRIES = 5;   // same as PayoutJob

    @Scheduled(fixedDelay = 60_000)
    public void run() {
        for (Refund r : refunds.lockPending(50)) {             // new in P1: row lock, one job per refund
            retry.run(r, MAX_TRIES, () -> card.refund(r));      // existing retry, new CardClient.refund
            refunds.save(r.sent());
            events.publish("refund.done", RefundDone.of(r));    // existing: through the outbox
        }
    }
}

