export async function requestRefund(id: string, amount: string) {   // same shape as cancelOrder()
  return fetch(`/api/refunds`, {
    method: 'POST',
    headers: { 'Idempotency-Key': crypto.randomUUID() },
    body: JSON.stringify({ orderId: id, amount }),
    signal: AbortSignal.timeout(5000),
  });
}

